<?php foreach(array('InvoiceNumber'=>array('Nomor nota tagihan','text',100),'InvoiceDate'=>array('Tanggal invoice','date',10),'PeriodStart'=>array('Periode dokumen mulai','date',10),'PeriodEnd'=>array('Periode dokumen sampai','date',10)) as $key=>$field): ?><div class="col-sm-6 form-group"><label><?= $field[0] ?></label><input type="<?= $field[1] ?>" name="<?= $key ?>" class="form-control" maxlength="<?= $field[2] ?>" required value="<?= html_escape(isset($form[$key])?$form[$key]:'') ?>"></div><?php endforeach; ?></div>
