<details style="margin:15px 0"><summary class="btn btn-default">Jatuh Tempo, Penandatangan &amp; Catatan (opsional)</summary><div class="row" style="margin-top:15px"><?php foreach(array('DueDate'=>array('Jatuh tempo (kosong = 7 hari setelah invoice)','date',10),'Signatory'=>array('Nama penandatangan','text',150),'SignatoryTitle'=>array('Jabatan penandatangan','text',200)) as $key=>$field): ?><div class="col-sm-4 form-group"><label><?= $field[0] ?></label><input type="<?= $field[1] ?>" class="form-control" name="<?= $key ?>" maxlength="<?= $field[2] ?>" value="<?= html_escape(isset($form[$key])?$form[$key]:'') ?>"></div><?php endforeach; ?></div>
<div class="form-group"><label>Alamat perusahaan</label><textarea name="CustomerAddress" maxlength="1000" class="form-control"><?= html_escape(isset($form['CustomerAddress'])?$form['CustomerAddress']:'') ?></textarea></div><div class="form-group"><label>Catatan / informasi pembayaran</label><textarea name="Notes" maxlength="1000" class="form-control"><?= html_escape(isset($form['Notes'])?$form['Notes']:'') ?></textarea></div></details>
<div class="form-group"><label>Dasar volume jasa administrasi BBM</label><p><label><input type="radio" name="SelectDO" value="all" <?= empty($form['SelectDO'])||$form['SelectDO']!=='selected'?'checked':'' ?>> Semua dokumen perusahaan dalam periode</label> &nbsp; <label><input type="radio" name="SelectDO" value="selected" <?= isset($form['SelectDO'])&&$form['SelectDO']==='selected'?'checked':'' ?>> Hanya dokumen terpilih di bawah</label></p><small>Klik Preview untuk menampilkan DO atau SPP sesuai perusahaan, sumber, dan periode. Tarif mengikuti Basic Harga yang berlaku pada tanggal dokumen; volume dihitung satu kali.</small>
<?php if(!empty($available_deliveries)): ?><table class="table table-bordered"><tr><th>Pilih</th><th>DO / Tanggal</th><th>Kapal</th><th>Liter</th></tr><?php foreach($available_deliveries as $r): ?><tr><td><input type="checkbox" name="DeliveryIDs[]" value="<?= (int)$r['DeliveryID'] ?>" <?= !isset($form['DeliveryIDs'])||in_array($r['DeliveryID'],$form['DeliveryIDs'])?'checked':'' ?>></td><td><?= html_escape($r['DONumber'].' / '.$r['DeliveryDate']) ?></td><td><?= html_escape($r['VesselName']) ?></td><td><?= number_format($r['Quantity'],3,',','.') ?></td></tr><?php endforeach; ?></table><?php endif; ?><?php if(!empty($available_spps)): ?><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Pilih</th><th>Surat Pengantar Pengiriman</th><th>Tanggal</th><th>No. Polisi / Nama Kapal</th><th>Liter</th></tr></thead><tbody><?php foreach($available_spps as $r): ?><tr><td><input type="checkbox" name="CaptureIDs[]" value="<?= (int)$r['CaptureID'] ?>" <?= !isset($form['CaptureIDs'])||in_array($r['CaptureID'],$form['CaptureIDs'])?'checked':'' ?>></td><td><a target="_blank" rel="noopener" href="<?= site_url('Pipeline_spp/review/'.$r['CaptureID']) ?>"><?= html_escape('SPP #'.$r['CaptureID'].' / LO '.$r['LONumber'].' / DO-Shipment '.$r['ShipmentNo']) ?></a></td><td><?= html_escape(substr($r['DeliveryDate'],0,10)) ?></td><td><?= html_escape($r['VehicleOrVessel']) ?></td><td><?= number_format($r['OrderedLiters'],3,',','.') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><button class="btn btn-primary" name="action" value="preview">Hitung / Preview</button>
