</form></div></div></section></div>
<script>(function(){var branch=document.getElementById('invoice-branch'),company=document.getElementById('invoice-company'),source=document.getElementById('invoice-source');function filter(){Array.prototype.forEach.call(company.options,function(o){if(!o.value)return;var show=o.getAttribute('data-branch')===branch.value&&o.getAttribute('data-source')===source.value;o.hidden=!show;o.disabled=!show;if(!show&&o.selected)company.value='';});company.dispatchEvent(new Event('change',{bubbles:true}));}branch.addEventListener('change',filter);source.addEventListener('change',filter);filter();})();</script>
